package com.example.examplemod.steel;

import com.example.examplemod.network.SteelConverterGuidePayload;
import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.EntityBlock;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.BlockStateProperties;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.neoforge.network.PacketDistributor;

public final class SteelConverterControllerBlock extends Block implements EntityBlock{
    public SteelConverterControllerBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(BlockStateProperties.HORIZONTAL_FACING,Direction.NORTH));}
    @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(BlockStateProperties.HORIZONTAL_FACING);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING,c.getHorizontalDirection().getOpposite());}
    @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new SteelConverterControllerBlockEntity(p,s);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){if(l.isClientSide())return null;return(a,p,b,e)->{if(a instanceof ServerLevel sl&&e instanceof SteelConverterControllerBlockEntity c)SteelConverterControllerBlockEntity.serverTick(sl,p,b,c);};}
    @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(l.isClientSide())return InteractionResult.SUCCESS;if(!(l instanceof ServerLevel sl)||!(l.getBlockEntity(p) instanceof SteelConverterControllerBlockEntity c))return InteractionResult.PASS;var v=c.validateNow(sl);player.sendSystemMessage(Component.translatable("message.createcityexpansioncore.steel_converter.status",c.state().name(),v.correctBlocks(),v.requiredBlocks(),c.inputAmount(sl),c.outputAmount(sl),SteelConverterOutputBlockEntity.CAPACITY,c.progress()*100,c.power()/1000));if(player instanceof ServerPlayer sp)PacketDistributor.sendToPlayer(sp,new SteelConverterGuidePayload(p));return InteractionResult.SUCCESS;}
}
